?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin - Users</title><link rel="stylesheet" href="../assets/app.css"></head><body><div class="admin-wrap"><div class="admin-head"><div><h1>Admin Panel</h1><div class="small">Employee login, permissions and data access</div></div><div class="toolbar"><a class="btn" href="../dashboard.php">Dashboard</a><a class="btn primary" href="user_edit.php">Add employee</a><a class="btn" href="../logout.php">Logout</a></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Data access</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['username'])?></td><td><span class="badge"><?=e($u['role'])?></span></td><td><span class="badge <?=$u['active']?'ok':'off'?>"><?=$u['active']?'Active':'Disabled'?></span></td><td><?=e($u['role']==='admin'?'All data':($u['data_scope']==='all'?'All coordinators':'Selected coordinators'))?></td><td><?=e($u['created_at'])?></td><td><a href="user_edit.php?id=<?=(int)$u['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div><div class="notice warn" style="margin-top:18px">Employees only receive the receivables rows allowed by their coordinator scope. Menu permissions are also applied after login.</div></div></body></html>
